1	<title>Proving Ground</title>
2	<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap">
3	<style>
4	:root{
5	  --bg:#f1f3f6;--surface:#fcfcfb;--surface-2:#f4f5f7;--ink:#14171c;--muted:#55606d;--line:#d8dde4;--line-strong:#b9c1cb;
6	  --accent:#1f6f8b;--accent-ink:#ffffff;--focus:#1f6f8b;
7	  --s1:#2a78d6;--s2:#eb6834;--s3:#1baf7a;--s4:#eda100;--s5:#e87ba4;--s6:#4a3aa7;
8	  --good:#0ca30c;--critical:#d03b3b;--neutral:#6b7480;--running:#1f6f8b;
9	  --seq-1:#cde2fb;--seq-2:#9ec5f4;--seq-3:#6da7ec;--seq-4:#3987e5;--seq-5:#256abf;--seq-6:#184f95;--seq-7:#0d366b;
10	  --radius:4px;
11	}
12	@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){
13	  --bg:#111417;--surface:#1a1a19;--surface-2:#202326;--ink:#e8eaed;--muted:#a3abb5;--line:#2b3139;--line-strong:#3d4652;
14	  --accent:#6cc0d3;--accent-ink:#0f1316;--focus:#6cc0d3;
15	  --s1:#3987e5;--s2:#d95926;--s3:#199e70;--s4:#c98500;--s5:#d55181;--s6:#9085e9;
16	  --neutral:#8b95a1;--running:#6cc0d3;
17	  --seq-1:#184f95;--seq-2:#1c5cab;--seq-3:#256abf;--seq-4:#2a78d6;--seq-5:#3987e5;--seq-6:#6da7ec;--seq-7:#9ec5f4;
18	}}
19	:root[data-theme="dark"]{
20	  --bg:#111417;--surface:#1a1a19;--surface-2:#202326;--ink:#e8eaed;--muted:#a3abb5;--line:#2b3139;--line-strong:#3d4652;
21	  --accent:#6cc0d3;--accent-ink:#0f1316;--focus:#6cc0d3;
22	  --s1:#3987e5;--s2:#d95926;--s3:#199e70;--s4:#c98500;--s5:#d55181;--s6:#9085e9;
23	  --neutral:#8b95a1;--running:#6cc0d3;
24	  --seq-1:#184f95;--seq-2:#1c5cab;--seq-3:#256abf;--seq-4:#2a78d6;--seq-5:#3987e5;--seq-6:#6da7ec;--seq-7:#9ec5f4;
25	}
26	*{box-sizing:border-box}
27	[hidden]{display:none!important}
28	body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 "IBM Plex Sans",ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;padding-block:0 4rem;padding-inline:clamp(16px,3vw,40px)}
29	a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}
30	:focus-visible{outline:2px solid var(--focus);outline-offset:2px}
31	.mono,.num,td.num,th.num,.cell-grid,.rows td,.rows th{font-family:"IBM Plex Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums}
32	h1{font:600 clamp(2rem,4vw,2.75rem)/1.05 Fraunces,Georgia,"Times New Roman",serif;letter-spacing:-0.01em;margin:0;text-wrap:balance}
33	h2{font:600 1.05rem/1.3 "IBM Plex Sans",system-ui,sans-serif;margin:0 0 .75rem;letter-spacing:.01em}
34	h3{font:500 .95rem/1.3 "IBM Plex Sans",system-ui,sans-serif;margin:0 0 .5rem}
35	.eyebrow{font-size:.72rem;text-transform:uppercase;letter-spacing:.12em;color:var(--muted);font-weight:500}
36	header{max-width:80rem;margin:0 auto;padding-block:2.25rem 1.5rem;display:grid;gap:1rem}
37	header p.lede{max-width:64ch;margin:0;color:var(--muted);font-size:1rem}
38	.stats{display:flex;flex-wrap:wrap;gap:.5rem 2rem;padding-block:.75rem;border-block:1px solid var(--line)}
39	.stat b{display:block;font:500 1.35rem/1.1 "IBM Plex Mono",monospace;font-variant-numeric:tabular-nums}
40	.stat span{font-size:.78rem;color:var(--muted)}
41	main{max-width:80rem;margin:0 auto;display:grid;gap:2.25rem}
42	section{display:grid;gap:.75rem}
43	.section-head{display:flex;flex-wrap:wrap;align-items:baseline;gap:.5rem 1.25rem}
44	.section-head p{margin:0;color:var(--muted);max-width:70ch}
45	.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:1rem}
46	.two{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:1.25rem}
47	@media (max-width:900px){.two{grid-template-columns:minmax(0,1fr)}}
48	/* verdict strip */
49	.verdicts{display:grid;grid-template-columns:repeat(auto-fill,minmax(19rem,1fr));gap:.75rem}
50	.verdict{display:grid;grid-template-rows:auto auto 1fr auto;gap:.5rem;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:.85rem .95rem;border-left-width:4px}
51	.verdict[data-verdict="promote"]{border-left-color:var(--good)}
52	.verdict[data-verdict="reject"]{border-left-color:var(--critical)}
53	.verdict[data-verdict="inconclusive"]{border-left-color:var(--neutral)}
54	.verdict[data-verdict="running"]{border-left-color:var(--running)}
55	.verdict .top{display:flex;justify-content:space-between;gap:.5rem;align-items:flex-start}
56	.verdict .name{font-weight:600}
57	.verdict .arms{color:var(--muted);font-size:.82rem;line-height:1.4}
58	.verdict .arms b{color:var(--ink);font-weight:500}
59	.verdict .counts{display:grid;grid-template-columns:1fr 1fr;gap:.5rem;font-size:.82rem}
60	.verdict .counts .num{font-size:1.15rem;font-weight:500;display:block}
61	.pill{display:inline-flex;align-items:center;gap:.35rem;font-size:.72rem;font-weight:600;letter-spacing:.06em;text-transform:uppercase;padding:.15rem .5rem;border-radius:999px;border:1px solid var(--line-strong);color:var(--ink);white-space:nowrap}
62	.pill::before{content:"";width:.5rem;height:.5rem;border-radius:50%;background:var(--neutral)}
63	.pill.promote::before{background:var(--good)}.pill.reject::before{background:var(--critical)}.pill.running::before{background:var(--running)}
64	.tag{display:inline-block;font-size:.7rem;color:var(--muted);border:1px solid var(--line);border-radius:3px;padding:0 .35rem;letter-spacing:.04em}
65	.interval svg{width:100%;height:38px;display:block}
66	.interval text{font-family:"IBM Plex Mono",monospace;font-size:10px;fill:var(--muted)}
67	/* charts */
68	.bars{display:grid;gap:.45rem}
69	.bar-row{display:grid;grid-template-columns:8.5rem minmax(0,1fr) 5.5rem;align-items:center;gap:.6rem;font-size:.85rem}
70	.bar-row .label{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
71	.bar-track{height:14px;background:var(--surface-2);border-radius:3px;position:relative;overflow:hidden}
72	.bar-fill{height:100%;border-radius:3px}
73	.bar-row .value{text-align:right}
74	.legend{display:flex;flex-wrap:wrap;gap:.4rem 1rem;font-size:.8rem;color:var(--muted)}
75	.legend i{display:inline-block;width:.7rem;height:.7rem;border-radius:2px;vertical-align:-1px;margin-right:.35rem}
76	/* matrix */
77	.matrix-wrap{overflow-x:auto}
78	table.matrix{border-collapse:separate;border-spacing:2px;font-size:.78rem}
79	table.matrix th{font-weight:500;color:var(--muted);text-align:left;padding:.15rem .35rem;white-space:nowrap}
80	table.matrix th.col{writing-mode:vertical-rl;transform:rotate(180deg);text-align:left;vertical-align:bottom;padding:.35rem .1rem;max-height:9rem}
81	table.matrix td{min-width:2.6rem;height:1.7rem;text-align:center;border-radius:3px;font-family:"IBM Plex Mono",monospace;font-variant-numeric:tabular-nums}
82	table.matrix td.empty{background:transparent;color:var(--line-strong)}
83	table.matrix td.r0{background:var(--surface-2);color:var(--ink)}
84	table.matrix td.r1{background:var(--seq-1);color:var(--ink)}table.matrix td.r2{background:var(--seq-2);color:var(--ink)}table.matrix td.r3{background:var(--seq-3);color:#0b0b0b}
85	table.matrix td.r4{background:var(--seq-4);color:#fff}table.matrix td.r5{background:var(--seq-5);color:#fff}table.matrix td.r6{background:var(--seq-6);color:#fff}table.matrix td.r7{background:var(--seq-7);color:#fff}
86	:root[data-theme="dark"] table.matrix td.r3,:root[data-theme="dark"] table.matrix td.r4{color:#fff}
87	:root[data-theme="dark"] table.matrix td.r6,:root[data-theme="dark"] table.matrix td.r7{color:#0b0b0b}
88	@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) table.matrix td.r3,:root:not([data-theme="light"]) table.matrix td.r4{color:#fff}:root:not([data-theme="light"]) table.matrix td.r6,:root:not([data-theme="light"]) table.matrix td.r7{color:#0b0b0b}}
89	table.matrix td .tier{display:block;font-size:.6rem;color:var(--muted)}
90	.toggles{display:flex;gap:.35rem;flex-wrap:wrap}
91	button.toggle,button.chip{font:inherit;font-size:.78rem;background:var(--surface);color:var(--ink);border:1px solid var(--line-strong);border-radius:999px;padding:.2rem .7rem;cursor:pointer}
92	button.toggle[aria-pressed="true"],button.chip[aria-pressed="true"]{background:var(--accent);color:var(--accent-ink);border-color:var(--accent)}
93	/* timeline */
94	.timeline svg{width:100%;height:auto;display:block}
95	.timeline text{font-family:"IBM Plex Mono",monospace;font-size:10px;fill:var(--muted)}
96	.timeline rect.run{rx:2;cursor:pointer}
97	.timeline rect.run:hover{stroke:var(--ink);stroke-width:1}
98	.timeline .lane{fill:var(--muted);font-size:10.5px}
99	/* records table */
100	.controls{display:flex;flex-wrap:wrap;gap:.5rem 1rem;align-items:center}
101	.controls input[type="search"]{font:inherit;padding:.3rem .6rem;border:1px solid var(--line-strong);border-radius:var(--radius);background:var(--surface);color:var(--ink);min-width:14rem}
102	.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:var(--radius);background:var(--surface)}
103	table.records{border-collapse:collapse;width:100%;font-size:.82rem;min-width:70rem}
104	table.records th,table.records td{padding:.45rem .55rem;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
105	table.records th{position:sticky;top:0;background:var(--surface-2);font-weight:600;white-space:nowrap;cursor:pointer;user-select:none}
106	table.records th[aria-sort="ascending"]::after{content:" \25B4"}table.records th[aria-sort="descending"]::after{content:" \25BE"}
107	table.records td.num,table.records th.num{text-align:right;font-family:"IBM Plex Mono",monospace;font-variant-numeric:tabular-nums}
108	table.records tr.record{cursor:pointer}
109	table.records tr.record:hover td{background:var(--surface-2)}
110	table.records tr.detail td{background:var(--surface-2);padding:.75rem .75rem 1rem}
111	.detail-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,3fr);gap:1rem}
112	@media (max-width:1000px){.detail-grid{grid-template-columns:minmax(0,1fr)}}
113	.detail p{margin:0 0 .5rem;max-width:80ch}
114	.detail dl{display:grid;grid-template-columns:auto 1fr;gap:.15rem .75rem;margin:0;font-size:.8rem}
115	.detail dt{color:var(--muted)}
116	.rows{width:100%;border-collapse:collapse;font-size:.76rem}
117	.rows th,.rows td{padding:.2rem .4rem;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap}
118	.rows th:first-child,.rows td:first-child,.rows th:nth-child(2),.rows td:nth-child(2){text-align:left}
119	.rows td.yes{color:var(--good);font-weight:600}.rows td.no{color:var(--critical);font-weight:600}
120	.attempts i{display:inline-block;width:.45rem;height:.7rem;margin-right:2px;background:var(--line-strong);vertical-align:middle;border-radius:1px}
121	.attempts i.pass{background:var(--good)}
122	.kind{display:inline-block;font-size:.7rem;font-weight:600;letter-spacing:.05em;text-transform:uppercase;padding:0 .4rem;border-radius:3px;border:1px solid var(--line-strong);color:var(--muted)}
123	.kind[data-kind="experiment"]{border-color:var(--s1);color:var(--s1)}.kind[data-kind="fleet"]{border-color:var(--s2);color:var(--s2)}
124	.kind[data-kind="district"]{border-color:var(--s3);color:var(--s3)}.kind[data-kind="program"]{border-color:var(--s6);color:var(--s6)}
125	.kind[data-kind="live"]{border-color:var(--running);color:var(--running)}.kind[data-kind="partial"]{border-style:dashed}
126	.badge-running{color:var(--running);font-weight:600}
127	/* readings */
128	table.plain{border-collapse:collapse;width:100%;font-size:.82rem}
129	table.plain th,table.plain td{padding:.35rem .5rem;border-bottom:1px solid var(--line);text-align:left}
130	table.plain td.num,table.plain th.num{text-align:right;font-family:"IBM Plex Mono",monospace;font-variant-numeric:tabular-nums}
131	.notes{display:grid;gap:.5rem;font-size:.9rem;max-width:80ch}
132	.notes p{margin:0}
133	footer{max-width:80rem;margin:3rem auto 0;color:var(--muted);font-size:.8rem}
134	.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
135	@media (prefers-reduced-motion:no-preference){.pulse{animation:pulse 1.6s ease-in-out infinite}@keyframes pulse{50%{opacity:.35}}}
136	</style>
137	<header>
138	  <div class="eyebrow">DeepSeek Harness · Daliesk</div>
139	  <h1>Proving Ground</h1>
140	  <p class="lede">Every recorded run of the bench on the operator's subscription, folded from the session logs on disk: what certified, at which attempt, at what cost, and which comparisons hold above the bench's own noise.</p>
141	  <div class="stats" id="stats"></div>
142	</header>
143	<main>
144	  <section id="live-section" hidden>
145	    <div class="section-head"><h2>Running now</h2><p>Folded from the run directory's session logs at build time; a run in flight has no verdict yet.</p></div>
146	    <div class="verdicts" id="live"></div>
147	  </section>
148	  <section>
149	    <div class="section-head"><h2>Verdicts</h2><p>Each card is one paired comparison: certificates per arm, the paired delta with its bootstrap interval, and the verdict rule read on that interval. Frozen pairs ran as one experiment; offline folds pair two separately recorded runs.</p></div>
150	    <div class="toggles" id="verdict-filters"></div>
151	    <div class="verdicts" id="verdicts"></div>
152	  </section>
153	  <div class="two">
154	    <section class="panel">
155	      <div class="section-head"><h2>Product models on sealed tier 5</h2><p>Plain single-model arms on the harness loop over the eight audited tasks, two repetitions at seed 2, three attempts; every sealed run of the same arm is pooled.</p></div>
156	      <div id="models"></div>
157	    </section>
158	    <section class="panel">
159	      <div class="section-head"><h2>Cost of a certificate</h2><p>Output tokens spent per certificate earned: each arm's output tokens over all its cells, divided by the certificates it produced.</p></div>
160	      <div id="cost"></div>
161	    </section>
162	  </div>
163	  <section class="panel">
164	    <div class="section-head"><h2>Difficulty matrix</h2><p>Certification rate per environment and route over sealed runs; a cell reads certified of run. Routes are the first rung, then the ladder, then the implementer.</p></div>
165	    <div class="toggles" id="matrix-toggles"></div>
166	    <div class="matrix-wrap" id="matrix"></div>
167	  </section>
168	  <section class="panel timeline">
169	    <div class="section-head"><h2>When it ran</h2><p>Each bar is one record from its first session to its last, by kind. Click a bar to open the record below.</p></div>
170	    <div id="timeline"></div>
171	  </section>
172	  <section>
173	    <div class="section-head"><h2>Records</h2><p>One row per recorded run; click a row for its cells and its README paragraph.</p></div>
174	    <div class="controls" id="record-controls"></div>
175	    <div class="table-wrap"><table class="records" id="records"></table></div>
176	  </section>
177	  <div class="two">
178	    <section class="panel">
179	      <div class="section-head"><h2>Routing, read offline</h2><p>Over the three single-model arms at seed 2: an oracle picks the cheapest certifying model per cell; a cascade tries the models in order and pays every stage.</p></div>
180	      <div id="routing"></div>
181	    </section>
182	    <section class="panel">
183	      <div class="section-head"><h2>Noise floor</h2><p>Run-to-run agreement of one arm on the same sixteen cells. A paired delta inside one arm's own flip rate says nothing.</p></div>
184	      <div id="repeatability"></div>
185	    </section>
186	  </section>
187	  <section class="panel" id="dataset-section" hidden>
188	    <div class="section-head"><h2>Training corpus</h2><p id="dataset-lede"></p></div>
189	    <div class="two" id="dataset"></div>
190	  </section>
191	  <section class="panel">
192	    <div class="section-head"><h2>How to read this page</h2></div>
193	    <div class="notes" id="notes"></div>
194	  </section>
195	</main>
196	<footer id="footer"></footer>
197	<script id="data" type="application/json">/*__DATA__*/</script>
198	<script>
199	(() => {
200	  const D = JSON.parse(document.getElementById('data').textContent)
201	  const $ = (id) => document.getElementById(id)
202	  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c])
203	  const fmt = (n) => n === undefined || n === null || Number.isNaN(n) ? '–' : Number(n).toLocaleString('en-US')
204	  const secs = (s) => s === undefined || s === null ? '–' : s < 3600 ? `${Math.round(s / 60)} min` : `${(s / 3600).toFixed(1)} h`
205	  const when = (iso) => iso ? iso.replace('T', ' ').slice(0, 16) + ' UTC' : '–'
206	  const signed = (x) => (x > 0 ? '+' : '') + Number(x).toFixed(4).replace(/0+$/, '').replace(/\.$/, '')
207	  const pct = (a, b) => b ? Math.round((a / b) * 100) : 0
208	  const SERIES = ['var(--s1)', 'var(--s2)', 'var(--s3)', 'var(--s4)', 'var(--s5)', 'var(--s6)']
209	  const linkRecord = (name) => `${D.linkBase}data/proving-ground/${name}/manifest.json`
210	
211	  // ---- stats
212	  $('stats').innerHTML = [
213	    [D.summary.records, 'records'], [D.summary.cells, 'cells run'], [D.summary.certified, 'certificates'],
214	    [D.summary.experiments, 'frozen experiments'], [D.summary.folds, 'offline folds'], [D.summary.environments, 'environments'],
215	  ].map(([n, l]) => `<div class="stat"><b>${fmt(n)}</b><span>${l}</span></div>`).join('')
216	    + `<div class="stat"><b class="mono" style="font-size:1rem">${esc(D.head.slice(0, 9))}</b><span>head · built ${esc(when(D.builtAt))}</span></div>`
217	
218	  // ---- interval bar (SVG): axis -1..1 clipped to the widest interval, 0 line, minimum-delta tick
219	  function intervalSvg(delta, interval, minimumDelta) {
220	    const W = 300, H = 38, pad = 14
221	    const lo = Math.min(-0.25, (interval?.lower ?? delta) - 0.05), hi = Math.max(0.25, (interval?.upper ?? delta) + 0.05)
222	    const span = Math.max(hi, -lo)
223	    const x = (v) => pad + ((v + span) / (2 * span)) * (W - 2 * pad)
224	    const y = 20
225	    const parts = [`<line x1="${pad}" y1="${y}" x2="${W - pad}" y2="${y}" stroke="var(--line-strong)" stroke-width="1"/>`,
226	      `<line x1="${x(0)}" y1="6" x2="${x(0)}" y2="34" stroke="var(--muted)" stroke-width="1" stroke-dasharray="2 2"/>`]
227	    if (minimumDelta) parts.push(`<line x1="${x(minimumDelta)}" y1="12" x2="${x(minimumDelta)}" y2="28" stroke="var(--good)" stroke-width="1"/>`)
228	    if (interval) parts.push(`<rect x="${x(interval.lower)}" y="${y - 5}" width="${Math.max(2, x(interval.upper) - x(interval.lower))}" height="10" rx="2" fill="var(--accent)" opacity=".35"/>`)
229	    parts.push(`<circle cx="${x(delta)}" cy="${y}" r="4.5" fill="var(--accent)" stroke="var(--surface)" stroke-width="2"/>`)
230	    parts.push(`<text x="${pad}" y="35" text-anchor="start">${(-span).toFixed(2)}</text><text x="${x(0)}" y="35" text-anchor="middle">0</text><text x="${W - pad}" y="35" text-anchor="end">+${span.toFixed(2)}</text>`)
231	    return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="delta ${signed(delta)} with interval ${interval ? signed(interval.lower) + ' to ' + signed(interval.upper) : 'absent'}">${parts.join('')}</svg>`
232	  }
233	
234	  // ---- verdict cards
235	  const verdictLabel = { promote: 'promote', reject: 'reject', inconclusive: 'inconclusive', running: 'running' }
236	  function verdictCard(e) {
237	    const v = e.verdict ?? 'running'
238	    const count = (arm) => arm && arm.cells ? `<span class="num">${arm.certified} <small>of ${arm.cells}</small></span>` : '<span class="num">–</span>no cell ran'
239	    const counts = `<div class="counts"><div>${count(e.baseline)}baseline</div><div>${count(e.candidate)}candidate</div></div>`
240	    return `<article class="verdict" data-verdict="${v}" data-method="${esc(e.method)}">
241	      <div class="top"><div><div class="name">${esc(e.label)}</div><div class="arms"><b>${esc(e.baselineLabel)}</b> vs <b>${esc(e.candidateLabel)}</b></div></div><span class="pill ${v}">${verdictLabel[v]}</span></div>
242	      <div class="arms"><span class="tag">${esc(e.method)}</span> <span class="tag">tier ${esc(e.tier ?? '–')}</span> <span class="tag">${e.seedsPaired ?? 0} paired</span> ${e.errors ? `<span class="tag">${e.errors} cell errors</span>` : ''}</div>
243	      ${counts}
244	      <div class="interval">${e.delta === undefined ? '' : intervalSvg(e.delta, e.interval, e.minimumDelta)}<div class="arms">Δ ${e.delta === undefined ? '–' : signed(e.delta)}${e.interval ? ` [${signed(e.interval.lower)}, ${signed(e.interval.upper)}]` : ''} · <a href="${esc(e.href)}">${esc(e.source)}</a></div></div>
245	    </article>`
246	  }
