import { readFileSync } from 'node:fs'
import { JSDOM } from 'jsdom'

const html = readFileSync(process.argv[2], 'utf8')
const dom = new JSDOM(html, { runScripts: 'dangerously' })
const section = dom.window.document.getElementById('loop-section')
console.log('loop section hidden:', section.hidden)
const rows = [...dom.window.document.querySelectorAll('#loop tbody tr')]
console.log('rows:', rows.length)
for (const row of rows) console.log([...row.querySelectorAll('td')].map(td => td.textContent.trim()).join(' | '))
console.log('records rows:', dom.window.document.querySelectorAll('#records tbody tr').length)
console.log('verdict cards:', dom.window.document.querySelectorAll('#verdicts article').length)
console.log('timeline lanes:', [...dom.window.document.querySelectorAll('#timeline text.lane')].map(t => t.textContent).join(','))

